package watch

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"time"

	"github.com/fsnotify/fsnotify"
)

// Library is the minimal library row the watcher needs: the id scans are
// triggered with and the root path the adapter watches. The cmd-side
// Deps.Libraries closure maps store rows into it — the package never
// imports mellifera's store or access packages (D1).
type Library struct {
	ID       int64
	RootPath string
}

// Deps are the cmd-built closures the service reads the world through —
// every store read and scan access arrives pre-built at the composition
// root (the internal/browse posture), keeping the package a pure leaf.
type Deps struct {
	// Libraries lists the currently known libraries. Read at Run start
	// and re-read on every reconcile tick, so the watch set follows
	// library CRUD without the package knowing the store.
	Libraries func(ctx context.Context) ([]Library, error)

	// Scan triggers one full scan of a library (scan.Run — the walk's
	// clean-drain tail is the tombstone sweep). Fired on quiet-window
	// expiry and on the reconcile backstop; a trigger finding a scan in
	// flight joins it (the cmd-side single-flight, D4).
	Scan func(ctx context.Context, libraryID int64) error
}

// Config carries the two timing knobs, floored and defaulted cmd-side
// (main.go's env resolvers) — the package takes them as given.
type Config struct {
	// ReconcileInterval is the periodic backstop tick: refresh the
	// library set and trigger a scan for every watched library.
	ReconcileInterval time.Duration

	// Debounce is the quiet window: how long a library root must sit
	// still after its last filesystem event before one scan fires.
	Debounce time.Duration
}

// Service is the lifecycle owner: the Run loop (task 1.2's adapter)
// feeds filesystem events and reconcile ticks to the pure trigger
// engine, which decides when each library's scan fires through Deps.
type Service struct {
	deps Deps
	cfg  Config
	eng  *engine
}

// NewService constructs the service over the given closures and knobs.
func NewService(deps Deps, cfg Config) *Service {
	return &Service{deps: deps, cfg: cfg, eng: newEngine(cfg.Debounce)}
}

// Run blocks for the process lifetime: it installs the initial watch set
// from Deps.Libraries, then selects on filesystem events (fed to the
// engine's observe), the reconcile ticker (a watch-set refresh followed
// by the per-library backstop trigger), and quiet-window expiry (one
// Deps.Scan per expired window), returning nil on ctx.Done. Every scan
// trigger dispatches its own goroutine — the loop NEVER awaits a scan
// inline (D3's dispatch law: the loop keeps observing while a scan runs,
// which the dirty-mid-run + completed(ok) re-arm law depends on). Watcher
// and trigger errors log WARN, never fatal.
func (s *Service) Run(ctx context.Context) error {
	l, err := s.newRunLoop()
	if err != nil {
		return err
	}
	defer l.close()
	s.refreshLibrarySet(ctx, l.ws) // initial install; a failed read logs WARN and starts empty
	return l.loop(ctx)
}

// runLoop is one Run invocation's state: the ONE fsnotify watcher, the
// watch set it backs, the fire timer for the earliest quiet-window
// deadline, and the reconcile ticker (nil channel when the knob is
// disabled). Owned by the Run goroutine alone.
type runLoop struct {
	svc        *Service
	watcher    *fsnotify.Watcher
	ws         *watchSet
	timer      *time.Timer
	ticker     *time.Ticker
	reconcileC <-chan time.Time
	wake       chan struct{} // completed() nudges the loop to re-arm the timer
}

func (s *Service) newRunLoop() (*runLoop, error) {
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		return nil, fmt.Errorf("watch: new watcher: %w", err)
	}
	l := &runLoop{
		svc:     s,
		watcher: watcher,
		ws:      newWatchSet(watcher),
		timer:   stoppedTimer(),
		wake:    make(chan struct{}, 1),
	}
	if s.cfg.ReconcileInterval > 0 {
		l.ticker = time.NewTicker(s.cfg.ReconcileInterval)
		l.reconcileC = l.ticker.C
	}
	return l, nil
}

func (l *runLoop) close() {
	if l.ticker != nil {
		l.ticker.Stop()
	}
	l.timer.Stop()
	_ = l.watcher.Close()
}

// loop is the event loop proper: re-arm the fire timer against the
// engine's earliest deadline, then select until ctx is cancelled.
func (l *runLoop) loop(ctx context.Context) error {
	for {
		l.armNextFire()
		select {
		case <-ctx.Done():
			return nil
		case ev, ok := <-l.watcher.Events:
			if !ok {
				return errors.New("watch: event channel closed")
			}
			l.svc.handleEvent(ev, l.ws)
		case err := <-l.watcher.Errors:
			slog.Warn("watch: watcher error", "error", err)
		case <-l.timer.C:
			l.fireDue(ctx)
		case <-l.reconcileC:
			l.reconcile(ctx)
		case <-l.wake:
		}
	}
}

// fireDue scans every watched library whose quiet window has expired at
// now — dueFires arms, so exactly one scan fires per window.
func (l *runLoop) fireDue(ctx context.Context) {
	now := time.Now()
	for _, id := range l.ws.libraryIDs() {
		if l.svc.eng.dueFires(now, id) {
			l.svc.dispatchScan(ctx, id, l.wake)
		}
	}
}

// reconcile is the periodic backstop: the watch set follows library CRUD
// (D6 — install new roots, drop deleted ones), then every watched
// library triggers; one already running is marked dirty instead (the
// trailing-scan law).
func (l *runLoop) reconcile(ctx context.Context) {
	l.svc.refreshLibrarySet(ctx, l.ws)
	for _, id := range l.ws.libraryIDs() {
		if l.svc.eng.backstop(id) {
			l.svc.dispatchScan(ctx, id, l.wake)
		}
	}
}

// refreshLibrarySet re-reads Deps.Libraries and diffs the watch set:
// new roots get installed, deleted roots dropped. A failed read logs
// WARN and keeps the previous set — the next tick retries.
func (s *Service) refreshLibrarySet(ctx context.Context, ws *watchSet) {
	libs, err := s.deps.Libraries(ctx)
	if err != nil {
		slog.Warn("watch: library set read failed", "error", err)
		return
	}
	current := make(map[string]int64, len(libs))
	for _, lib := range libs {
		current[filepath.Clean(lib.RootPath)] = lib.ID
	}
	for root, id := range current {
		if _, ok := ws.roots[root]; !ok {
			ws.addRoot(root, id)
		}
	}
	for root := range ws.roots {
		if _, ok := current[root]; !ok {
			ws.removeRoot(root)
		}
	}
}

// handleEvent routes one fsnotify event to its owning library: Chmod is
// ignored; every other event extends the owner's quiet window (or marks
// it dirty mid-run); a directory Create extends the watch set (walk + Add
// the subtree), a directory Remove/Rename drops it. Events outside every
// root are ignored.
func (s *Service) handleEvent(ev fsnotify.Event, ws *watchSet) {
	if ev.Has(fsnotify.Chmod) {
		return
	}
	id, ok := ws.owner(ev.Name)
	if !ok {
		return
	}
	s.eng.observe(time.Now(), id)
	if ev.Has(fsnotify.Create) {
		if fi, err := os.Stat(ev.Name); err == nil && fi.IsDir() {
			ws.installTree(ev.Name)
		}
	}
	if ev.Has(fsnotify.Remove) || ev.Has(fsnotify.Rename) {
		ws.dropUnder(ev.Name)
	}
}

// dispatchScan fires one scan in its own goroutine, logging errors WARN —
// never fatal. The trailing completed() nudges the loop's wake channel so
// the fire timer re-arms on any trailing-scan deadline the completion set.
func (s *Service) dispatchScan(ctx context.Context, id int64, wake chan struct{}) {
	go func() {
		err := s.deps.Scan(ctx, id)
		if err != nil {
			slog.Warn("watch: scan trigger failed", "library_id", id, "error", err)
		}
		s.eng.completed(time.Now(), id, err == nil)
		select {
		case wake <- struct{}{}:
		default:
		}
	}()
}

// armNextFire points the fire timer at the earliest pending quiet-window
// deadline; with none pending the timer is stopped.
func (l *runLoop) armNextFire() {
	deadline, ok := l.svc.eng.nextDeadline()
	if !ok {
		l.stopTimer()
		return
	}
	d := time.Until(deadline)
	if d < 0 {
		d = 0
	}
	l.stopTimer()
	l.timer.Reset(d)
}

func (l *runLoop) stopTimer() {
	if !l.timer.Stop() {
		select {
		case <-l.timer.C:
		default:
		}
	}
}

// stoppedTimer returns an idle timer — armed later by armNextFire.
func stoppedTimer() *time.Timer {
	t := time.NewTimer(0)
	if !t.Stop() {
		<-t.C
	}
	return t
}
